#define PI 3.14

vec2 logPolar2D(vec2 pos) {
    // Apply the forward log-polar map
    pos = vec2(log(length(pos)), atan(pos.y, pos.x));

    // Scale everything so tiles will fit nicely in the ]-pi,pi] interval
    pos *= 6.0/PI;

    // Convert pos to single-tile coordinates
    pos = fract(pos) - .8;

    return pos;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime*2.;   
    vec2 ouv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    vec2 uv = iMouse.z < 1. ? logPolar2D(ouv) : ouv;    


    vec3 col = vec3(0.);    
    // rings
    col.r += 0.5 + 0.5*sin(-t+uv.x*(PI*2.));
    // rays
    col.g += 0.5 + 0.5*cos(-t+uv.y*(PI*2.));
    // whirls
    col.b += 0.5 + 0.5*cos(-t*11.+uv.y*(PI*2.)+sin(uv.x)*(PI*2.2));
    // fade
    col -= length(ouv);

    // Output to screen
    fragColor = vec4(col,1.0);
}
